const hm  = s => { const [h,m]=String(s).split(":").map(Number); return h*60+m; };
const mm  = m => { const v=(((m%1440)+1440)%1440); return String(Math.floor(v/60)).padStart(2,"0")+":"+String(v%60).padStart(2,"0"); };
const dur = m => m>=60 ? `${Math.floor(m/60)} h ${String(m%60).padStart(2,"0")}` : `${m} min`;
const hmn = m => `${Math.floor(m/60)}h${String(m%60).padStart(2,"0")}`;
const num = v => Math.round(v).toLocaleString("pl-PL");
const pad = (n,l=3) => String(n).padStart(l,"0");
const iso = d => d.toISOString().slice(0,10);
const addD = (s,n) => { const d=new Date(s+"T12:00:00Z"); d.setUTCDate(d.getUTCDate()+n); return iso(d); };
const dowOf = s => (new Date(s+"T12:00:00Z").getUTCDay()+6)%7;
const DNI = ["PON","WT","ŚR","CZW","PT","SOB","ND"];
const DNIL = ["poniedziałek","wtorek","środa","czwartek","piątek","sobota","niedziela"];
const MIES = ["stycznia","lutego","marca","kwietnia","maja","czerwca","lipca","sierpnia","września","października","listopada","grudnia"];
const dataPL = s => { const d=new Date(s+"T12:00:00Z"); return `${d.getUTCDate()} ${MIES[d.getUTCMonth()]} ${d.getUTCFullYear()}`; };
const MSK = ["JAN","FEB","MAR","APR","MAY","JUN","JUL","AUG","SEP","OCT","NOV","DEC"];
const dataKr = s => { const d=new Date(s+"T12:00:00Z"); return `${String(d.getUTCDate()).padStart(2,"0")}${MSK[d.getUTCMonth()]}`; };
const dataPelna = s => dataKr(s)+s.slice(0,4);

function prng(seed){ let s=seed>>>0; return ()=>{ s=(s+0x6D2B79F5)|0; let t=Math.imul(s^(s>>>15),1|s);
  t=(t+Math.imul(t^(t>>>7),61|t))^t; return ((t^(t>>>14))>>>0)/4294967296; }; }
const hsh = str => { let h=2166136261; for(const c of String(str)) h=Math.imul(h^c.charCodeAt(0),16777619); return h>>>0; };
const pick = (r,a) => a[Math.floor(r()*a.length)];
const gcKm = (a,b) => { const A=P(a), B=P(b); if(!A||!B) return 0;
  const R2=6371, r=Math.PI/180, dla=(B[0]-A[0])*r, dlo=(B[1]-A[1])*r;
  const h=Math.sin(dla/2)**2+Math.cos(A[0]*r)*Math.cos(B[0]*r)*Math.sin(dlo/2)**2;
  return Math.round(2*R2*Math.asin(Math.sqrt(h))); };
const rint = (r,a,b) => a+Math.floor(r()*(b-a+1));

/* strefy czasowe: offset portu w minutach dla danej doby */
const _off = {};
function off(port, dateISO){
  const k=port+dateISO; if(_off[k]!==undefined) return _off[k];
  const p=DB.L[port]; if(!p){ _off[k]=0; return 0; }
  const D=new Date(dateISO+"T12:00:00Z"); let v=0;
  try{ const x={};
    new Intl.DateTimeFormat("en-US",{timeZone:p[2],hour12:false,year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"})
      .formatToParts(D).forEach(y=>x[y.type]=y.value);
    v=Math.round((Date.UTC(+x.year,+x.month-1,+x.day,+x.hour%24,+x.minute)-D.getTime())/60000);
  }catch(e){ v=0; }
  _off[k]=v; return v;
}

