/* Kratka w tle: osobna warstwa pod trescia. Kolor z palety, skok i moc z ustawien,
   gradient zanikania realizowany maska — siatka gasnie ku krawedziom. */
const SIATKA_DOM={siatka:1,siatkaRozmiar:24,siatkaMoc:45,siatkaZanik:55,siatkaTyp:"kratka",siatkaKolor:"neutral"};
function siatkaUst(ust){ return {...SIATKA_DOM,...(ust||{})}; }
function Kratka({T,ust}){
  const u=siatkaUst(ust);
  if(!u.siatka) return null;
  const px=+u.siatkaRozmiar||24;
  const bazowy={neutral:T.gridRGB,akcent:hexRGB(T.orF),blekit:hexRGB(T.bl)}[u.siatkaKolor]||T.gridRGB;
  const maxA=u.siatkaKolor==="neutral"?(T.gridMax??0.15):(T.gridMax??0.15)*0.62;
  const a=((+u.siatkaMoc||45)/100)*maxA;
  const c=`rgba(${bazowy},${a.toFixed(3)})`;
  const obraz=u.siatkaTyp==="kropki"
    ? `radial-gradient(${c} 1.1px,transparent 1.1px)`
    : u.siatkaTyp==="linie"
    ? `linear-gradient(${c} 1px,transparent 1px)`
    : `linear-gradient(${c} 1px,transparent 1px),linear-gradient(90deg,${c} 1px,transparent 1px)`;
  const z=Math.max(0,Math.min(100,+u.siatkaZanik||0));
  const maska=z<=2?null
    :`radial-gradient(120% 100% at 50% 0%, rgba(0,0,0,1) 0%, rgba(0,0,0,${(1-z/100).toFixed(2)}) ${100-z*0.6}%, rgba(0,0,0,0) 100%)`;
  return <div aria-hidden style={{position:"fixed",inset:0,zIndex:0,pointerEvents:"none",
    backgroundImage:obraz,backgroundSize:`${px}px ${px}px`,
    backgroundPosition:u.siatkaTyp==="kropki"?"center":"-1px -1px",
    ...(maska?{WebkitMaskImage:maska,maskImage:maska}:{})}}/>;
}
const hexRGB=h=>{const x=h.replace("#","");
  return [0,2,4].map(i=>parseInt(x.slice(i,i+2),16)).join(",");};
/* podglad kratki w prostokacie ustawien */
function siatkaTlo(T,ust){
  const u=siatkaUst(ust);
  if(!u.siatka) return {backgroundImage:"none",WebkitMaskImage:"none",maskImage:"none"};
  const px=Math.max(6,Math.round((+u.siatkaRozmiar||24)*0.6));
  const bazowy={neutral:T.gridRGB,akcent:hexRGB(T.orF),blekit:hexRGB(T.bl)}[u.siatkaKolor]||T.gridRGB;
  const maxA=u.siatkaKolor==="neutral"?(T.gridMax??0.15):(T.gridMax??0.15)*0.62;
  const a=((+u.siatkaMoc||45)/100)*maxA*2.2;
  const c=`rgba(${bazowy},${Math.min(0.5,a).toFixed(3)})`;
  const obraz=u.siatkaTyp==="kropki"?`radial-gradient(${c} 1.1px,transparent 1.1px)`
    :u.siatkaTyp==="linie"?`linear-gradient(${c} 1px,transparent 1px)`
    :`linear-gradient(${c} 1px,transparent 1px),linear-gradient(90deg,${c} 1px,transparent 1px)`;
  const z=Math.max(0,Math.min(100,+u.siatkaZanik||0));
  const maska=z<=2?null:`linear-gradient(180deg,rgba(0,0,0,1) 0%,rgba(0,0,0,${(1-z/100).toFixed(2)}) 100%)`;
  return {backgroundImage:obraz,backgroundSize:`${px}px ${px}px`,
    WebkitMaskImage:maska||"none",maskImage:maska||"none"};
}

function Awatar({T,ust,r=32}){
  const zr=(ust.imie||ust.login||"").trim();
  const ini=zr.split(/\s+/).map(x=>x[0]).filter(Boolean).slice(0,2).join("").toUpperCase();
  return (<div style={{width:r,height:r,borderRadius:r/2,flexShrink:0,display:"flex",
    alignItems:"center",justifyContent:"center",background:ini?T.orS:T.surf3,
    border:`1px solid ${ini?T.orB:T.bd}`,font:`500 ${r*0.36}px ${MONO}`,color:ini?T.or:T.tx3,letterSpacing:".02em"}}>
    {ini||<svg width={r*0.5} height={r*0.5} viewBox="0 0 24 24" fill="none" stroke={T.tx3} strokeWidth="1.8"
      strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="8" r="3.6"/><path d="M4.5 20a7.5 7.5 0 0 1 15 0"/></svg>}
  </div>);
}


