/* ══════════════════════ PASEK CZASU ══════════════════════ */
function PasekCzasu({T,odc,min,kon}){
  const W=1000, pad=46, yCisza=13, y=60, H=124;
  const t0=odc.abs-45;
  const t1=Math.max(odc.absSta+min+80, odc.absSta+160);
  const x=t=>pad+Math.max(0,Math.min(1,(t-t0)/(t1-t0)))*(W-pad*2);
  const dOff=off(odc.d,odc.data);
  const cf=P(odc.d)?.[8];
  let okno=null;
  if(cf){ const a2=hm(cf[0]), b2=hm(cf[1]);
    for(let k=-2;k<=2&&!okno;k++){
      const s2=a2-dOff+k*1440, e2=(b2>a2?b2:b2+1440)-dOff+k*1440;
      if(e2>t0&&s2<t1) okno={s:Math.max(s2,t0),e:Math.min(e2,t1),typ:cf[2],txt:cf[0]+"–"+cf[1]};
    }
  }
  const zn=[{t:odc.abs,g:mm(odc.stdLok),op:"odlot "+odc.o,kol:T.tx2,r:3.2},
            {t:odc.absSta,g:mm(odc.staLok),op:"przylot planowy",kol:T.tx3,r:3.2}];
  if(min>0) zn.push({t:odc.absSta+min,g:mm(kon?.staLokOp??0),op:"przylot z opóźnieniem",kol:T.orF,r:4.4,akc:1});
  let ost=-1e9;
  zn.sort((p1,p2)=>p1.t-p2.t).forEach(z=>{ const px=x(z.t); z.dol=px-ost<132; if(!z.dol) ost=px; });
  const prog3=odc.absSta+180, progOp=odc.absSta+(kon?.prog||180);
  const progi=[[progOp,"opieka",kon?.prog||180],[prog3,"3 h",180]];
  return (
   <svg viewBox={`0 0 ${W} ${H}`} style={{width:"100%",height:"auto",display:"block"}} aria-label="oś czasu rejsu">
    {/* pasmo ciszy nocnej ma wlasny poziom nad osia */}
    {okno&&<>
      <rect x={x(okno.s)} y={yCisza-9} width={Math.max(2,x(okno.e)-x(okno.s))} height={18} rx="2"
        fill={okno.typ===1?T.orS:T.blS} stroke={okno.typ===1?T.orB:T.blB} strokeWidth="1"/>
      <text x={x(okno.s)+7} y={yCisza+4} fill={okno.typ===1?T.or:T.bl}
        style={{font:`500 9px ${MONO}`,letterSpacing:".05em"}}>
        {x(okno.e)-x(okno.s)>150?`CISZA NOCNA ${okno.txt}`:"CISZA"}</text>
      <line x1={x(okno.s)} y1={yCisza+9} x2={x(okno.s)} y2={y-11} stroke={okno.typ===1?T.orB:T.blB}
        strokeWidth="1" strokeDasharray="2 3"/>
    </>}
    <line x1={pad} y1={y} x2={W-pad} y2={y} stroke={T.bd} strokeWidth="1"/>
    <line x1={x(odc.abs)} y1={y} x2={x(odc.absSta)} y2={y} stroke={T.tx3} strokeWidth="2"/>
    {min>0&&<line x1={x(odc.absSta)} y1={y} x2={x(odc.absSta+min)} y2={y} stroke={T.orF} strokeWidth="2"/>}
    {progi.map(([t,l,pr],i)=>{
      const akt=min>=pr;
      return <g key={i} opacity={x(t)>pad+8&&x(t)<W-pad-8?1:0}>
        <line x1={x(t)} y1={y-7} x2={x(t)} y2={y+7} stroke={akt?T.orF:T.bd} strokeWidth="1" strokeDasharray="2 2"/>
        <text x={x(t)} y={y+(i?34:21)} textAnchor="middle" fill={akt?T.or:T.tx3}
          style={{font:`500 7.5px ${SANS}`,letterSpacing:".09em",textTransform:"uppercase"}}>{l}</text></g>;})}
    {zn.map((z,i)=><g key={i}>
      <circle cx={x(z.t)} cy={y} r={z.r} fill={z.akc?T.orF:T.pan} stroke={z.kol} strokeWidth="1.5"/>
      <text x={x(z.t)} y={z.dol?y+52:y-16} textAnchor="middle" fill={z.akc?T.or:T.tx}
        style={{font:`400 10.5px ${MONO}`}}>{z.g}</text>
      <text x={x(z.t)} y={z.dol?y+63:y-27} textAnchor="middle" fill={T.tx3}
        style={{font:`500 7.5px ${SANS}`,letterSpacing:".08em",textTransform:"uppercase"}}>{z.op}</text>
    </g>)}
   </svg>);
}

/* ══════════════════════ WYSZUKIWARKA REJSU ══════════════════════ */
function Szukajka({T,data,onWybierz,szeroka,ph="Numer rejsu, port albo trasa"}){
  const [q,setQ]=React.useState(""); const [ot,setOt]=React.useState(false);
  const wyn=React.useMemo(()=>{
    if(q.trim().length<2) return [];
    const s=q.trim().toUpperCase().replace(/\s+/g," ");
    const d=dzienSwiata(data);
    return d.odc.filter(o=>o.nr.includes(s)||o.o===s||o.d===s||(o.o+"-"+o.d).includes(s)||(o.o+o.d).includes(s)||
      nazwa(o.d).toUpperCase().includes(s)||nazwa(o.o).toUpperCase().includes(s)).slice(0,9);
  },[q,data]);
  return (<div style={{position:"relative",width:szeroka?"100%":320}}>
    <input value={q} placeholder={ph} onChange={e=>{setQ(e.target.value);setOt(true);}} onFocus={()=>setOt(true)}
      onBlur={()=>setTimeout(()=>setOt(false),160)}
      style={{...inpSt(T),font:`400 ${szeroka?14:12.5}px/1.4 ${MONO}`,padding:szeroka?"14px 16px":"9px 11px",background:T.pan}}/>
    {ot&&wyn.length>0&&<div style={{position:"absolute",top:"calc(100% + 4px)",left:0,right:0,zIndex:40,
      background:T.pan,border:`1px solid ${T.ln}`,borderRadius:4,overflow:"hidden",maxHeight:330,overflowY:"auto"}}>
      {wyn.map(o=><button key={o.nr} onMouseDown={()=>{onWybierz(o);setQ("");setOt(false);}}
        className="lo-row" style={{display:"grid",gridTemplateColumns:"78px minmax(0,1fr) 62px 54px",gap:12,alignItems:"center",width:"100%",
          padding:"10px 14px",background:"transparent",border:"none",borderBottom:`1px solid ${T.ln2}`,cursor:"pointer",textAlign:"left"}}>
        <span style={{font:`400 12px ${MONO}`,color:T.ac}}>{o.nr}</span>
        <span style={{font:`400 12px ${SANS}`,color:T.tx}}>{o.o} → {o.d} <span style={{color:T.tx3}}>{nazwa(o.d)}</span></span>
        <span style={{font:`400 11px ${MONO}`,color:T.tx2}}>{mm(o.stdLok)}</span>
        <span style={{font:`400 10px ${MONO}`,color:T.tx3}}>{o.regTyp||o.typ}</span>
      </button>)}
    </div>}
  </div>);
}

/* ══════════════════════ KARTY REJSÓW ══════════════════════ */
